package com.yingliu.api.admin.moderation;
import com.yingliu.api.admin.content.shared.PageResponse;import com.yingliu.api.admin.security.AdminPermissionAuthorizer;import com.yingliu.common.api.ApiResponse;import com.yingliu.framework.web.TraceIdFilter;import com.yingliu.service.content.shared.ServicePage;import com.yingliu.service.moderation.ModerationService;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.Max;import jakarta.validation.constraints.Min;import org.springframework.web.bind.annotation.*;import java.time.LocalDateTime;
@RestController @RequestMapping("/api/v1/admin") public class ModerationController{
 private final ModerationService s;private final AdminPermissionAuthorizer a;public ModerationController(ModerationService s,AdminPermissionAuthorizer a){this.s=s;this.a=a;}
 @GetMapping("/comments") public ApiResponse<PageResponse<ModerationDtos.Comment>> comments(@RequestParam(defaultValue="1")@Min(1)long page,@RequestParam(defaultValue="20")@Min(1)@Max(100)long pageSize,@RequestParam(required=false)String status,@RequestParam(required=false)Long videoId,@RequestParam(required=false)String keyword,HttpServletRequest r){a.require("comment:view");ServicePage<ModerationService.Comment>x=s.comments(page,pageSize,status,videoId,keyword);return ApiResponse.ok(new PageResponse<>(x.items().stream().map(this::c).toList(),page,pageSize,x.total()),tid(r));}
 @GetMapping("/comments/{id}")public ApiResponse<ModerationDtos.Comment> comment(@PathVariable long id,HttpServletRequest r){a.require("comment:view");return ApiResponse.ok(c(s.comment(id)),tid(r));}
 @PostMapping("/comments/{id}/hide")public ApiResponse<ModerationDtos.Comment> hide(@PathVariable long id,@Valid@RequestBody ModerationDtos.Reason b,HttpServletRequest r){return ApiResponse.ok(c(s.hideComment(id,a.require("comment:hide"),b.reason())),tid(r));}
 @PostMapping("/comments/{id}/restore")public ApiResponse<ModerationDtos.Comment> restore(@PathVariable long id,HttpServletRequest r){return ApiResponse.ok(c(s.restoreComment(id,a.require("comment:restore"))),tid(r));}
 @DeleteMapping("/comments/{id}")public ApiResponse<ModerationDtos.Comment> delete(@PathVariable long id,@Valid@RequestBody ModerationDtos.Reason b,HttpServletRequest r){return ApiResponse.ok(c(s.deleteComment(id,a.require("comment:delete"),b.reason())),tid(r));}
 @PostMapping("/comments/batch/handle")public ApiResponse<ModerationDtos.BatchResult> batch(@Valid@RequestBody ModerationDtos.Batch b,HttpServletRequest r){long actor=a.require("comment:delete");java.util.List<Long> ok=new java.util.ArrayList<>(),fail=new java.util.ArrayList<>();for(Long id:b.commentIds()){try{if("HIDE".equalsIgnoreCase(b.action()))s.hideComment(id,actor,b.reason());else if("RESTORE".equalsIgnoreCase(b.action()))s.restoreComment(id,actor);else s.deleteComment(id,actor,b.reason());ok.add(id);}catch(RuntimeException e){fail.add(id);}}return ApiResponse.ok(new ModerationDtos.BatchResult(ok,fail),tid(r));}
 @GetMapping("/reports")public ApiResponse<PageResponse<ModerationDtos.Report>> reports(@RequestParam(defaultValue="1")@Min(1)long page,@RequestParam(defaultValue="20")@Min(1)@Max(100)long size,@RequestParam(required=false)String status,@RequestParam(required=false)String targetType,HttpServletRequest r){a.require("report:view");ServicePage<ModerationService.Report>x=s.reports(page,size,status,targetType);return ApiResponse.ok(new PageResponse<>(x.items().stream().map(this::rp).toList(),page,size,x.total()),tid(r));}
 @GetMapping("/reports/{id}")public ApiResponse<ModerationDtos.Report> report(@PathVariable long id,HttpServletRequest r){a.require("report:view");return ApiResponse.ok(rp(s.report(id)),tid(r));}
 @PostMapping("/reports/{id}/claim")public ApiResponse<ModerationDtos.Report> claim(@PathVariable long id,HttpServletRequest r){s.claimReport(id,a.require("report:claim"));return ApiResponse.ok(rp(s.report(id)),tid(r));}
 @PostMapping("/reports/{id}/resolve")public ApiResponse<ModerationDtos.Report> resolve(@PathVariable long id,@Valid@RequestBody ModerationDtos.Resolve b,HttpServletRequest r){s.resolveReport(id,a.require("report:resolve"),b.resolution(),b.note());return ApiResponse.ok(rp(s.report(id)),tid(r));}
 @PostMapping("/reports/{id}/reject")public ApiResponse<ModerationDtos.Report> reject(@PathVariable long id,@Valid @RequestBody ModerationDtos.Resolve b,HttpServletRequest r){s.rejectReport(id,a.require("report:reject"),b.note());return ApiResponse.ok(rp(s.report(id)),tid(r));}
 private ModerationDtos.Comment c(ModerationService.Comment x){return new ModerationDtos.Comment(""+x.id(),""+x.videoId(),x.videoTitle(),""+x.userId(),x.author(),x.content(),x.status(),x.riskLevel(),x.likeCount(),x.replyCount(),t(x.createdAt()),t(x.updatedAt()));}private ModerationDtos.Report rp(ModerationService.Report x){return new ModerationDtos.Report(""+x.id(),""+x.reporterId(),x.targetType(),""+x.targetId(),x.reasonCode(),x.description(),"CLAIMED".equals(x.status())?"PROCESSING":x.status(),x.riskLevel(),x.assigneeAdminId()==null?null:""+x.assigneeAdminId(),x.resolution(),x.resolutionNote(),t(x.resolvedAt()),t(x.createdAt()),t(x.updatedAt()));}private String t(LocalDateTime x){return x==null?null:x.toString();}private String tid(HttpServletRequest r){return(String)r.getAttribute(TraceIdFilter.ATTRIBUTE);}
}
